"""Apply the approved full-card template patch once on GitHub main."""
import base64
import subprocess
import zlib

PATCH = zlib.decompress(base64.b64decode(""))

def run(*args, input_data=None):
    return subprocess.run(args, input=input_data, check=False, capture_output=True)

check = run("git", "apply", "--check", input_data=PATCH)
if check.returncode == 0:
    subprocess.run(["git", "apply"], input=PATCH, check=True)
    print("Applied full-card template patch")
else:
    reverse = run("git", "apply", "--reverse", "--check", input_data=PATCH)
    if reverse.returncode == 0:
        print("Full-card template patch already applied")
    else:
        raise SystemExit(check.stderr.decode("utf-8", "replace"))
